// noise.h — Factorio-API-shaped noise primitives.
//
// These mimic the *behavior* of Factorio's noise expressions, not their
// bit-exact hashing. Seed semantics match: (seed0, seed1) keying so that
// different seed1 values give independent noise fields.
//
// Functions are pure (referentially transparent in (x, y, seed0, seed1)).

#ifndef NOISE_H
#define NOISE_H

#include <stdint.h>

// String → 32-bit ID. Factorio docs say string seed1 values are CRC32'd.
// We use a simple FNV-1a here — different from CRC32 but serves the same
// purpose: deterministic mapping from string to integer keys.
uint32_t noise_layer_id(const char *s);

// Single-octave gradient noise. Roughly Perlin-shaped output in [-1, 1] before
// output_scale is applied.
double basis_noise(double x, double y,
                   uint32_t seed0, uint32_t seed1,
                   double input_scale, double output_scale,
                   double offset_x, double offset_y);

// Multi-octave: sum of basis_noise at successively halved scales.
double multioctave_noise(double x, double y, double persistence,
                         uint32_t seed0, uint32_t seed1, int octaves,
                         double input_scale, double output_scale,
                         double offset_x, double offset_y);

// Voronoi: jittered grid of points, one per cell.
// Returns:
//   - cell_id:     per-cell random value in [0, 1]
//   - pyramid:     scaled distance from current point to nearest cell edge,
//                  zero at cell boundary, peaking at cell center
//   - facet:       distance to 2nd-nearest point minus distance to nearest;
//                  zero at cell boundary, increasing into interior
//
// distance_type: 0=chebyshev, 1=manhattan, 2=euclidean (others not implemented)

double voronoi_cell_id(double x, double y, uint32_t seed0, uint32_t seed1,
                       int grid_size, int distance_type, double jitter);

double voronoi_pyramid_noise(double x, double y, uint32_t seed0, uint32_t seed1,
                             int grid_size, int distance_type, double jitter);

double voronoi_facet_noise(double x, double y, uint32_t seed0, uint32_t seed1,
                           int grid_size, int distance_type, double jitter);

#endif

