#include "noise.h"

#include <math.h>
#include <string.h>

// ============================================================================
// Hashing
// ============================================================================
//
// We need: (uint32, uint32, int32, int32) → uint32, fast and well-mixed.
// Used to seed gradient vectors at each integer lattice point in basis_noise,
// and to jitter Voronoi cell points.
//
// This is a knockoff of pcg_hash combined with a coordinate folding step.

static inline uint32_t pcg_mix(uint32_t x) {
    x = ((x >> ((x >> 28) + 4)) ^ x) * 0x45d9f3bU;
    x = ((x >> ((x >> 28) + 4)) ^ x) * 0x45d9f3bU;
    x = (x >> 16) ^ x;
    return x;
}

static inline uint32_t hash4(uint32_t a, uint32_t b, int32_t c, int32_t d) {
    uint32_t h = a;
    h = pcg_mix(h ^ b);
    h = pcg_mix(h ^ (uint32_t)c);
    h = pcg_mix(h ^ (uint32_t)d);
    return h;
}

uint32_t noise_layer_id(const char *s) {
    // FNV-1a 32-bit
    uint32_t h = 2166136261u;
    if (!s) return 0;
    for (; *s; ++s) {
        h ^= (unsigned char)*s;
        h *= 16777619u;
    }
    return h;
}

// ============================================================================
// basis_noise — value-noise with smoothstep interpolation
// ============================================================================
//
// Real Perlin uses gradient noise; Factorio's basis_noise is documented as a
// "Factorio single-octave noise" (no further detail). We implement value noise
// here: hash each integer lattice point to a value in [-1, 1], then
// quintic-interpolate. Behaviorally similar enough that algorithm tuning
// transfers.
//
// Note the docs' claim: "When given integer values for x, y and input_scale,
// the output is always 0." Value noise has this property naturally because
// at lattice points the output equals the lattice value, and for the output
// to always be 0 at integer x/y the lattice values themselves would all need
// to be 0 — that's not how Perlin works either. We don't enforce this exactly;
// it's not load-bearing for our algorithms.

static inline uint32_t lattice_hash(int32_t ix, int32_t iy,
                                    uint32_t seed0, uint32_t seed1) {
    return hash4(seed0, seed1, ix, iy);
}

static inline double lattice_value(int32_t ix, int32_t iy,
                                   uint32_t seed0, uint32_t seed1) {
    uint32_t h = lattice_hash(ix, iy, seed0, seed1);
    // Map to [-1, 1)
    return ((double)h / (double)UINT32_MAX) * 2.0 - 1.0;
}

static inline double smoothstep5(double t) {
    // Quintic: 6t^5 - 15t^4 + 10t^3 (Perlin's improved fade)
    return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

double basis_noise(double x, double y,
                   uint32_t seed0, uint32_t seed1,
                   double input_scale, double output_scale,
                   double offset_x, double offset_y) {
    double sx = (x + offset_x) * input_scale;
    double sy = (y + offset_y) * input_scale;

    int32_t ix = (int32_t)floor(sx);
    int32_t iy = (int32_t)floor(sy);
    double fx = sx - (double)ix;
    double fy = sy - (double)iy;

    double v00 = lattice_value(ix, iy, seed0, seed1);
    double v10 = lattice_value(ix + 1, iy, seed0, seed1);
    double v01 = lattice_value(ix, iy + 1, seed0, seed1);
    double v11 = lattice_value(ix + 1, iy + 1, seed0, seed1);

    double ux = smoothstep5(fx);
    double uy = smoothstep5(fy);

    double a = v00 + ux * (v10 - v00);
    double b = v01 + ux * (v11 - v01);
    double v = a + uy * (b - a);

    return v * output_scale;
}

// ============================================================================
// multioctave_noise
// ============================================================================

double multioctave_noise(double x, double y, double persistence,
                         uint32_t seed0, uint32_t seed1, int octaves,
                         double input_scale, double output_scale,
                         double offset_x, double offset_y) {
    double total = 0.0;
    double amplitude = 1.0;
    double freq = input_scale;
    double sum_amplitude = 0.0;

    for (int o = 0; o < octaves; ++o) {
        // Each octave gets a derived seed so layers are independent.
        uint32_t s1 = seed1 ^ pcg_mix((uint32_t)o + 1);
        total += basis_noise(x, y, seed0, s1, freq, 1.0,
                             offset_x, offset_y) * amplitude;
        sum_amplitude += amplitude;
        amplitude *= persistence;
        freq *= 2.0;
    }
    if (sum_amplitude > 0.0) total /= sum_amplitude;
    return total * output_scale;
}

// ============================================================================
// Voronoi
// ============================================================================
//
// Standard jittered-grid Voronoi: each integer cell of size grid_size has one
// candidate point at (cell_center + jitter * random_offset). To find cell
// memberships we check the 3x3 neighborhood of cells around the query point.

static inline double dist_metric(double dx, double dy, int distance_type) {
    double adx = fabs(dx), ady = fabs(dy);
    switch (distance_type) {
        case 0: return adx > ady ? adx : ady;        // chebyshev
        case 1: return adx + ady;                    // manhattan
        case 2: default: return sqrt(dx*dx + dy*dy); // euclidean
    }
}

// Helper: position of the candidate point inside cell (cx, cy).
static inline void voronoi_point(int32_t cx, int32_t cy,
                                 uint32_t seed0, uint32_t seed1,
                                 int grid_size, double jitter,
                                 double *out_x, double *out_y) {
    uint32_t h = hash4(seed0, seed1, cx, cy);
    // Two independent values in [0, 1) for x/y jitter
    double rx = (double)(h & 0xFFFF) / 65536.0;
    double ry = (double)((h >> 16) & 0xFFFF) / 65536.0;
    double cell_size = (double)grid_size;
    // Center-relative offset in [-0.5, 0.5] * jitter, then translated to cell origin
    double ox = (rx - 0.5) * jitter;
    double oy = (ry - 0.5) * jitter;
    *out_x = (cx + 0.5 + ox) * cell_size;
    *out_y = (cy + 0.5 + oy) * cell_size;
}

// Inner Voronoi pass: scans 3x3 around the query, finds nearest two points.
typedef struct {
    double d1, d2;          // distances to nearest, 2nd-nearest
    int32_t cx1, cy1;       // cell coordinates of nearest
} voronoi_result;

static voronoi_result voronoi_scan(double x, double y,
                                   uint32_t seed0, uint32_t seed1,
                                   int grid_size, int distance_type,
                                   double jitter) {
    double cell_size = (double)grid_size;
    int32_t qx = (int32_t)floor(x / cell_size);
    int32_t qy = (int32_t)floor(y / cell_size);

    voronoi_result r = { .d1 = 1e300, .d2 = 1e300, .cx1 = qx, .cy1 = qy };

    for (int dy = -1; dy <= 1; ++dy) {
        for (int dx = -1; dx <= 1; ++dx) {
            int32_t cx = qx + dx, cy = qy + dy;
            double px, py;
            voronoi_point(cx, cy, seed0, seed1, grid_size, jitter, &px, &py);
            double d = dist_metric(x - px, y - py, distance_type);
            if (d < r.d1) {
                r.d2 = r.d1;
                r.d1 = d;
                r.cx1 = cx;
                r.cy1 = cy;
            } else if (d < r.d2) {
                r.d2 = d;
            }
        }
    }
    return r;
}

double voronoi_cell_id(double x, double y, uint32_t seed0, uint32_t seed1,
                       int grid_size, int distance_type, double jitter) {
    voronoi_result r = voronoi_scan(x, y, seed0, seed1, grid_size,
                                    distance_type, jitter);
    // Per-cell random in [0, 1]. Use a different hash than the point-jitter
    // so cell_id and point position aren't correlated.
    uint32_t h = hash4(seed0 ^ 0xa5a5a5a5u, seed1, r.cx1, r.cy1);
    return (double)h / (double)UINT32_MAX;
}

double voronoi_pyramid_noise(double x, double y, uint32_t seed0, uint32_t seed1,
                             int grid_size, int distance_type, double jitter) {
    voronoi_result r = voronoi_scan(x, y, seed0, seed1, grid_size,
                                    distance_type, jitter);
    // distance to nearest, normalized by grid_size, returned as "interior depth"
    // The Factorio docs describe this as distance to the closest *edge*, not
    // the closest point; we approximate by (d2 - d1) / 2 which equals the
    // perpendicular distance to the perpendicular bisector between the two
    // closest points, i.e., the local cell wall.
    double depth = (r.d2 - r.d1) * 0.5;
    return depth / (double)grid_size;
}

double voronoi_facet_noise(double x, double y, uint32_t seed0, uint32_t seed1,
                           int grid_size, int distance_type, double jitter) {
    voronoi_result r = voronoi_scan(x, y, seed0, seed1, grid_size,
                                    distance_type, jitter);
    // d2 - d1: zero at cell wall, increasing into interior
    return (r.d2 - r.d1) / (double)grid_size;
}

