            int32_t cx = qx + dx, cy = qy + dy;
            double px, py;
            voronoi_point(cx, cy, seed0, seed1, grid_size, jitter, &px, &py);
            double d = dist_metric(x - px, y - py, distance_type);
            if (d < r.d1) {
                r.d2 = r.d1;
                r.d1 = d;
                r.cx1 = cx;
                r.cy1 = cy;
            } else if (d < r.d2) {
                r.d2 = d;
            }
        }
    }
    return r;
}

double voronoi_cell_id(double x, double y, uint32_t seed0, uint32_t seed1,
                       int grid_size, int distance_type, double jitter) {
    voronoi_result r = voronoi_scan(x, y, seed0, seed1, grid_size,
                                    distance_type, jitter);
    // Per-cell random in [0, 1]. Use a different hash than the point-jitter
    // so cell_id and point position aren't correlated.
    uint32_t h = hash4(seed0 ^ 0xa5a5a5a5u, seed1, r.cx1, r.cy1);
    return (double)h / (double)UINT32_MAX;
}

double voronoi_pyramid_noise(double x, double y, uint32_t seed0, uint32_t seed1,
                             int grid_size, int distance_type, double jitter) {
    voronoi_result r = voronoi_scan(x, y, seed0, seed1, grid_size,
                                    distance_type, jitter);
    // distance to nearest, normalized by grid_size, returned as "interior depth"
    // The Factorio docs describe this as distance to the closest *edge*, not
    // the closest point; we approximate by (d2 - d1) / 2 which equals the
    // perpendicular distance to the perpendicular bisector between the two
    // closest points, i.e., the local cell wall.
    double depth = (r.d2 - r.d1) * 0.5;
    return depth / (double)grid_size;
}

double voronoi_facet_noise(double x, double y, uint32_t seed0, uint32_t seed1,
                           int grid_size, int distance_type, double jitter) {
    voronoi_result r = voronoi_scan(x, y, seed0, seed1, grid_size,
                                    distance_type, jitter);
    // d2 - d1: zero at cell wall, increasing into interior
    return (r.d2 - r.d1) / (double)grid_size;
}

