#include "geology.h"
#include "noise.h"

#include <math.h>

// All tunable constants live here so they're easy to find and modify.
// These match the constants in geology-noise-expressions.lua.

// --- Layer 0: warp ---
#define WARP_COARSE_OUTPUT 1500.0
#define WARP_COARSE_SCALE  (1.0/4000.0)
#define WARP_COARSE_OCT    3
#define WARP_FINE_OUTPUT   80.0
#define WARP_FINE_SCALE    (1.0/400.0)
#define WARP_FINE_OCT      4

// --- Layer 1: cratons ---
#define CRATON_GRID        3000
#define CRATON_JITTER      0.95
#define CONT_BIAS_SCALE    (1.0/30000.0)
#define CONT_BIAS_OUTPUT   0.4
#define CONT_THRESHOLD     0.55

// --- Layer 2: pair classification ---
#define NEIGHBOR_OFFSET    400.0
#define BOUNDARY_THRESHOLD 0.15

// --- Layer 3: drainage ---
#define RIVER_VALLEY_WIDTH 0.15
#define REGIONAL_SCALE     (1.0/15000.0)
#define REGIONAL_OUTPUT    0.5
#define BASIN_REGIONAL_THRESHOLD -0.3
#define BASIN_COAST_THRESHOLD 0.25

// --- Layer 4: elevation ---
#define TRIBUTARY_SCALE    (1.0/600.0)
#define TRIBUTARY_OUTPUT   0.3
#define OROGEN_WIDTH       0.20
#define OROGEN_HEIGHT      1.5

// --- Layer 5: properties ---
#define SHIELD_INTERIOR_THRESHOLD 1500.0
#define SUTURE_NEAR_THRESHOLD     0.05

// ---- helpers ----
static inline double clampd(double v, double lo, double hi) {
    return v < lo ? lo : (v > hi ? hi : v);
}
static inline double maxd(double a, double b) { return a > b ? a : b; }
static inline double sqr(double v) { return v * v; }

// ============================================================================
// Layer 0: warp
// ============================================================================

void layer0_warp(double x, double y, const geo_ctx_t *ctx, geo_fields_t *f) {
    f->warp_coarse_x = multioctave_noise(x, y, 0.6,
        ctx->map_seed, noise_layer_id("warp-cx"), WARP_COARSE_OCT,
        WARP_COARSE_SCALE, WARP_COARSE_OUTPUT, 0, 0);
    f->warp_coarse_y = multioctave_noise(x, y, 0.6,
        ctx->map_seed, noise_layer_id("warp-cy"), WARP_COARSE_OCT,
        WARP_COARSE_SCALE, WARP_COARSE_OUTPUT, 0, 0);
    f->warp_fine_x = multioctave_noise(x, y, 0.5,
        ctx->map_seed, noise_layer_id("warp-fx"), WARP_FINE_OCT,
        WARP_FINE_SCALE, WARP_FINE_OUTPUT, 0, 0);
    f->warp_fine_y = multioctave_noise(x, y, 0.5,
        ctx->map_seed, noise_layer_id("warp-fy"), WARP_FINE_OCT,
        WARP_FINE_SCALE, WARP_FINE_OUTPUT, 0, 0);
    f->wx = x + f->warp_coarse_x + f->warp_fine_x;
    f->wy = y + f->warp_coarse_y + f->warp_fine_y;
}

// ============================================================================
// Layer 1: cratons
// ============================================================================

void layer1_cratons(const geo_ctx_t *ctx, geo_fields_t *f) {
    uint32_t s_craton = noise_layer_id("craton");

    f->craton_id = voronoi_cell_id(f->wx, f->wy,
        ctx->map_seed, s_craton, CRATON_GRID, 2, CRATON_JITTER);

    f->continental_bias = multioctave_noise(f->wx - f->warp_coarse_x - f->warp_fine_x,
                                            f->wy - f->warp_coarse_y - f->warp_fine_y,
                                            0.5,
        ctx->map_seed, noise_layer_id("pangaea"), 2,
        CONT_BIAS_SCALE, CONT_BIAS_OUTPUT, 0, 0);
    // ^ NOTE: continental_bias uses unwarped (x, y) per the Lua. We re-derive
    //   them from the warped values; equivalent and avoids passing originals.

    f->craton_continental = (f->craton_id + f->continental_bias > CONT_THRESHOLD) ? 1.0 : 0.0;

    f->craton_interior = voronoi_pyramid_noise(f->wx, f->wy,
        ctx->map_seed, s_craton, CRATON_GRID, 2, CRATON_JITTER) * (double)CRATON_GRID;

    f->suture_proximity = voronoi_facet_noise(f->wx, f->wy,
        ctx->map_seed, s_craton, CRATON_GRID, 2, CRATON_JITTER);
}

// ============================================================================
// Layer 2: cell-pair-aware boundary classification
// ============================================================================

void layer2_boundary(const geo_ctx_t *ctx, geo_fields_t *f) {
    uint32_t s_craton = noise_layer_id("craton");

    f->craton_id_east  = voronoi_cell_id(f->wx + NEIGHBOR_OFFSET, f->wy,
        ctx->map_seed, s_craton, CRATON_GRID, 2, CRATON_JITTER);
    f->craton_id_west  = voronoi_cell_id(f->wx - NEIGHBOR_OFFSET, f->wy,
        ctx->map_seed, s_craton, CRATON_GRID, 2, CRATON_JITTER);
    f->craton_id_north = voronoi_cell_id(f->wx, f->wy + NEIGHBOR_OFFSET,
        ctx->map_seed, s_craton, CRATON_GRID, 2, CRATON_JITTER);
    f->craton_id_south = voronoi_cell_id(f->wx, f->wy - NEIGHBOR_OFFSET,
        ctx->map_seed, s_craton, CRATON_GRID, 2, CRATON_JITTER);

    // Pick the offset whose cell_id differs most from self.
    double de = fabs(f->craton_id_east  - f->craton_id);
    double dw = fabs(f->craton_id_west  - f->craton_id);
    double dn = fabs(f->craton_id_north - f->craton_id);
    double ds = fabs(f->craton_id_south - f->craton_id);

    double max_d = de;
    f->neighbor_id = f->craton_id_east;
    if (dw > max_d) { max_d = dw; f->neighbor_id = f->craton_id_west; }
    if (dn > max_d) { max_d = dn; f->neighbor_id = f->craton_id_north; }
    if (ds > max_d) {              f->neighbor_id = f->craton_id_south; }

    f->pair_hash_input = f->craton_id + f->neighbor_id
                       + 4.0 * f->craton_id * f->neighbor_id;

    f->boundary_character = basis_noise(
        f->pair_hash_input * 1000.0, f->pair_hash_input * 1414.0,
        ctx->map_seed, noise_layer_id("boundary"),
        1.0 / 100.0, 1.0, 0, 0);

    if (f->boundary_character > BOUNDARY_THRESHOLD)         f->boundary_type = 2.0;
    else if (f->boundary_character < -BOUNDARY_THRESHOLD)   f->boundary_type = 1.0;
    else                                                    f->boundary_type = 0.0;
}

// ============================================================================
// Layer 3: drainage skeleton
// ============================================================================

void layer3_drainage(const geo_ctx_t *ctx, geo_fields_t *f) {
    f->river_depth_by_type =
        f->boundary_type > 1.5 ? 1.0 :
        f->boundary_type > 0.5 ? 1.4 :
        0.2;

    double valley_factor = maxd(0.0, 1.0 - f->suture_proximity / RIVER_VALLEY_WIDTH);
    f->river_cut = f->river_depth_by_type * sqr(valley_factor);

    f->coast_proximity = fabs(f->continental_bias);

    f->regional_elevation_character = multioctave_noise(f->wx, f->wy, 0.55,
        ctx->map_seed, noise_layer_id("regional"), 3,
        REGIONAL_SCALE, REGIONAL_OUTPUT, 0, 0);

    f->endorheic_indicator =
        (f->regional_elevation_character < BASIN_REGIONAL_THRESHOLD &&
         f->coast_proximity > BASIN_COAST_THRESHOLD) ? 1.0 : 0.0;

    if (f->endorheic_indicator > 0.5) {
        f->drainage_depth = f->coast_proximity * 2.0
                          + f->regional_elevation_character
                          - 0.4
                          - f->river_cut * 0.6;
    } else {
        f->drainage_depth = maxd(0.0,
            f->coast_proximity * 2.0
          + f->regional_elevation_character
          - f->river_cut * 0.6);
    }
}

// ============================================================================
// Layer 4: elevation
// ============================================================================

void layer4_elevation(const geo_ctx_t *ctx, geo_fields_t *f) {
    f->tributary_detail = TRIBUTARY_OUTPUT - fabs(multioctave_noise(
        f->wx, f->wy, 0.5,
        ctx->map_seed, noise_layer_id("tributaries"), 5,
        TRIBUTARY_SCALE, TRIBUTARY_OUTPUT, 0, 0));

    if (f->boundary_type > 1.5) {
        double m = maxd(0.0, 1.0 - f->suture_proximity / OROGEN_WIDTH);
        f->orogenic_uplift = sqr(m) * OROGEN_HEIGHT;
    } else {
        f->orogenic_uplift = 0.0;
    }

    if (f->craton_continental > 0.5) {
        f->elevation = f->drainage_depth
                     + f->tributary_detail
                     + f->orogenic_uplift
                     - f->river_cut * 0.4;
    } else {
        f->elevation = -0.2
                     - f->coast_proximity * 1.0
                     - f->regional_elevation_character * 0.3;
    }
}

// ============================================================================
// Layer 5: properties
// ============================================================================

void layer5_properties(const geo_ctx_t *ctx, geo_fields_t *f) {
    // tectonic_setting integer-encoded:
    // 0=ocean, 1=passive_margin, 2=shield, 3=platform, 4=orogen, 5=rift, 6=basin
    if (f->craton_continental < 0.5) {
        f->tectonic_setting = 0.0;
    } else if (f->endorheic_indicator > 0.5) {
        f->tectonic_setting = 6.0;
    } else if (f->suture_proximity < SUTURE_NEAR_THRESHOLD) {
        f->tectonic_setting = f->boundary_type > 1.5 ? 4.0 :
                              f->boundary_type > 0.5 ? 5.0 : 1.0;
    } else if (f->craton_interior > SHIELD_INTERIOR_THRESHOLD) {
        f->tectonic_setting = 2.0;
    } else {
        f->tectonic_setting = 3.0;
    }

    int t = (int)f->tectonic_setting;
    switch (t) {
        case 0: f->rock_age = 0.1; break;
        case 6: f->rock_age = 0.3; break;
        case 5: f->rock_age = 0.4; break;
        case 4: f->rock_age = 0.6; break;
        case 3: f->rock_age = 0.7; break;
        case 2: f->rock_age = 0.95; break;
        case 1: default: f->rock_age = 0.3; break;
    }

    f->crustal_thickness = 30.0 + f->elevation * 6.0
                         + (t == 4 ? 20.0 : 0.0);

    f->weathering_intensity = clampd(
        (1.0 - f->rock_age) * 0.5 + 0.5 - maxd(0.0, f->elevation) * 0.05,
        0.0, 1.0);

    f->sediment_thickness = maxd(0.0, -f->drainage_depth + 0.5)
                          + (t == 1 ? 0.4 : 0.0);

    // Mineral favorability fields
    double mn_felsic_noise = basis_noise(f->wx, f->wy,
        ctx->map_seed, noise_layer_id("min-felsic"),
        1.0/2000.0, 1.0, 0, 0);
    f->mineral_felsic = maxd(0.0,
        (t == 2 ? 0.7 : 0.0) +
        (t == 4 ? 0.5 : 0.0) +
        0.3 * mn_felsic_noise);

    double mn_mafic_noise = basis_noise(f->wx, f->wy,
        ctx->map_seed, noise_layer_id("min-mafic"),
        1.0/3000.0, 1.0, 0, 0);
    f->mineral_mafic = maxd(0.0,
        (t == 0 ? 0.6 : 0.0) +
        (t == 5 ? 0.8 : 0.0) +
        0.3 * mn_mafic_noise);

    double mn_hydro_noise = basis_noise(f->wx, f->wy,
        ctx->map_seed, noise_layer_id("min-hydro"),
        1.0/800.0, 1.0, 0, 0);
    double hydro_base = 0.0;
    if (f->suture_proximity < 0.1) {
        hydro_base = f->boundary_type > 1.5 ? 0.8 :
                     f->boundary_type > 0.5 ? 0.6 : 0.3;
    }
    f->mineral_hydrothermal = maxd(0.0, hydro_base + 0.2 * mn_hydro_noise);

    double placer_factor = sqr(maxd(0.0, 1.0 - f->suture_proximity / 0.05));
    f->mineral_placer = maxd(0.0, placer_factor * f->mineral_felsic * 0.7);

    f->mineral_evaporite = maxd(0.0, f->endorheic_indicator * 0.8);
}

// ============================================================================
// Driver
// ============================================================================

void geology_eval_all(double x, double y, const geo_ctx_t *ctx,
                      geo_fields_t *out) {
    layer0_warp(x, y, ctx, out);
    layer1_cratons(ctx, out);
    layer2_boundary(ctx, out);
    layer3_drainage(ctx, out);
    layer4_elevation(ctx, out);
    layer5_properties(ctx, out);
}

