// viz.h — color mapping, field registry, and rendering helpers.

#ifndef VIZ_H
#define VIZ_H

#include "geology.h"
#include <stdint.h>

// A field extractor — pulls one scalar out of a populated geo_fields_t.
// Two flavors: "continuous" fields (mapped through a value range to [0, 1])
// and "categorical" fields (integer-valued, mapped through a palette).

typedef enum { FIELD_CONTINUOUS, FIELD_CATEGORICAL } field_kind_t;

typedef struct {
    const char *name;
    field_kind_t kind;
    double (*extract)(const geo_fields_t *);
    double range_min, range_max;   // for continuous: input range mapped to [0,1]
} field_descriptor_t;

extern const field_descriptor_t FIELDS[];
extern const int FIELDS_COUNT;

// HSL → RGB conversion. h in [0, 1), s in [0, 1], l in [0, 1].
// Returns 0xRRGGBB packed for fenster's framebuffer (which expects 0x00RRGGBB).
uint32_t hsl_to_rgb(double h, double s, double l);

// Compose pixel from elevation + active hue field + active saturation field.
// elevation is mapped to L; hue field gives H; sat field gives S.
uint32_t pixel_from_fields(const geo_fields_t *f,
                           int hue_field_idx, int sat_field_idx);

#endif

