}

uint32_t pixel_from_fields(const geo_fields_t *f,
                           int hue_field_idx, int sat_field_idx) {
    // Elevation → L. Sea level at 0.0 elevation maps to L = 0.4 (dark).
    // Tall mountains around elevation 3.0 map to L ≈ 0.85.
    // Deep ocean around -1.5 maps to L ≈ 0.15.
    double e = f->elevation;
    double L = 0.4 + e * 0.15;
    if (L < 0.08) L = 0.08;
    if (L > 0.92) L = 0.92;

    const field_descriptor_t *hfd = &FIELDS[hue_field_idx];
    const field_descriptor_t *sfd = &FIELDS[sat_field_idx];

    double H = field_to_unit(hfd, hfd->extract(f));
    double S = field_to_unit(sfd, sfd->extract(f));

    return hsl_to_rgb(H, S, L);
}

