// main.c — fenster window, input handling, and rendering composition.
//
// Layout:
//   Window:        1024 x 768
//   Overview:        0..768  (768 x 768) showing entire continent
//   Sidebar:       768..1024 (256 wide) for zoom inset + status text
//     Zoom inset:  768..1024 x 0..256 (256 x 256)
//     Text area:   768..1024 x 256..768
//
// World coordinates: continent centered on (0, 0), spanning ±50000 tiles.
// (~100k tiles across — matches the "continental scale" choice.)
//
// Input:
//   R           re-seed (random new map_seed)
//   N / Shift+N cycle hue field forward / backward
//   M / Shift+M cycle saturation field forward / backward
//   Mouse move  re-center zoom inset on cursor
//   Mouse wheel zoom in/out (handled via +/- keys; fenster doesn't expose wheel)
//   + / -       zoom inset zooms in / out
//   ESC         quit

#define FENSTER_HEADER_ONLY 0
#include "fenster.h"
#include "geology.h"
#include "viz.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define WIN_W 1024
#define WIN_H 768
#define OVERVIEW_W 768
#define OVERVIEW_H 768
#define INSET_X    768
#define INSET_Y    0
#define INSET_W    256
#define INSET_H    256

// World extent the overview covers, in tiles. Continent at this scale.
#define WORLD_HALF 50000.0

static uint32_t buf[WIN_W * WIN_H];

static geo_ctx_t ctx;
static int hue_field_idx = 0;   // boundary_type
static int sat_field_idx = 8;   // suture_proximity
static double inset_cx = 0.0, inset_cy = 0.0;   // world coord at center of inset
static double inset_half = 5000.0;              // half-width of inset in tiles

// Tiny 5x7 bitmap font for status text. Just enough to read field names.
// Each glyph: 5 cols x 7 rows, packed as 7 bytes (one per row, low 5 bits used).
// Only printable ASCII 0x20..0x7E supported; missing glyphs render as blank.
//
// Generated/curated minimally for readability of the status line.
// (Provides A-Z, 0-9, space, ':', '_', '-', '+', '.', '/', '<', '>')

static const uint8_t font5x7[][7] = {
    // Index 0 = ' '
    {0,0,0,0,0,0,0},
    // We only fill in characters we use; others fall through to blank.
};

static void draw_glyph_blank(uint32_t *buffer, int x, int y, uint32_t color) {
    (void)buffer; (void)x; (void)y; (void)color;
}

// Minimalist text rendering: just draw small filled rectangles per character
// to label fields. We'll forgo a real font and instead use color-coded bars.
// This keeps the program dependency-free and lets you focus on the maps.

static void draw_label_bar(uint32_t *buffer, int x, int y, int w, uint32_t color) {
    for (int dy = 0; dy < 4; ++dy) {
        for (int dx = 0; dx < w; ++dx) {
            int px = x + dx, py = y + dy;
            if (px >= 0 && px < WIN_W && py >= 0 && py < WIN_H) {
                buffer[py * WIN_W + px] = color;
            }
        }
    }
}

// ============================================================================
// Rendering
// ============================================================================

static void render_overview(void) {
    // Each pixel covers (2*WORLD_HALF / OVERVIEW_W) tiles.
    double pixel_size = 2.0 * WORLD_HALF / OVERVIEW_W;

    for (int py = 0; py < OVERVIEW_H; ++py) {
        double wy = -WORLD_HALF + (py + 0.5) * pixel_size;
        for (int px = 0; px < OVERVIEW_W; ++px) {
            double wx = -WORLD_HALF + (px + 0.5) * pixel_size;

            geo_fields_t f;
            geology_eval_all(wx, wy, &ctx, &f);
            buf[py * WIN_W + px] = pixel_from_fields(&f,
                                                     hue_field_idx,
                                                     sat_field_idx);
        }
    }

    // Mark inset rectangle in overview.
    int rx0 = (int)((inset_cx - inset_half + WORLD_HALF) / pixel_size);
    int ry0 = (int)((inset_cy - inset_half + WORLD_HALF) / pixel_size);
    int rx1 = (int)((inset_cx + inset_half + WORLD_HALF) / pixel_size);
    int ry1 = (int)((inset_cy + inset_half + WORLD_HALF) / pixel_size);
    if (rx0 < 0) rx0 = 0; if (ry0 < 0) ry0 = 0;
    if (rx1 >= OVERVIEW_W) rx1 = OVERVIEW_W - 1;
    if (ry1 >= OVERVIEW_H) ry1 = OVERVIEW_H - 1;
    for (int x = rx0; x <= rx1; ++x) {
        if (ry0 >= 0 && ry0 < OVERVIEW_H) buf[ry0 * WIN_W + x] = 0xFFFFFFu;
        if (ry1 >= 0 && ry1 < OVERVIEW_H) buf[ry1 * WIN_W + x] = 0xFFFFFFu;
    }
    for (int y = ry0; y <= ry1; ++y) {
        if (rx0 >= 0 && rx0 < OVERVIEW_W) buf[y * WIN_W + rx0] = 0xFFFFFFu;
        if (rx1 >= 0 && rx1 < OVERVIEW_W) buf[y * WIN_W + rx1] = 0xFFFFFFu;
    }
}

static void render_inset(void) {
    double pixel_size = 2.0 * inset_half / INSET_W;

    for (int iy = 0; iy < INSET_H; ++iy) {
        double wy = inset_cy - inset_half + (iy + 0.5) * pixel_size;
        for (int ix = 0; ix < INSET_W; ++ix) {
            double wx = inset_cx - inset_half + (ix + 0.5) * pixel_size;

            geo_fields_t f;
            geology_eval_all(wx, wy, &ctx, &f);
            buf[(INSET_Y + iy) * WIN_W + (INSET_X + ix)] =
                pixel_from_fields(&f, hue_field_idx, sat_field_idx);
        }
    }
}

static void render_sidebar_text(void) {
    // Clear the text area below the inset
    for (int y = INSET_Y + INSET_H; y < WIN_H; ++y) {
        for (int x = INSET_X; x < WIN_W; ++x) {
            buf[y * WIN_W + x] = 0x202028u;
        }
    }

    // Sidebar shows two color bars indicating which fields are bound to H and S.
    // Top half: hue field's color across its range, with a marker for the field's
    // index in FIELDS.
    // Without a real font, we show each field's index as a column of bars:
    //   Hue field marker:  red bar, position = hue_field_idx
    //   Sat field marker:  blue bar, position = sat_field_idx

    int bar_y_h = INSET_Y + INSET_H + 20;
    int bar_y_s = INSET_Y + INSET_H + 40;

    // Draw a tick row: one tick per field in the registry, colored
    // green for hue field, blue for sat field.
    int avail_w = INSET_W - 16;
    int tick_w = avail_w / FIELDS_COUNT;
    if (tick_w < 2) tick_w = 2;

    for (int i = 0; i < FIELDS_COUNT; ++i) {
        int x = INSET_X + 8 + i * tick_w;
        uint32_t color_h = (i == hue_field_idx) ? 0x00FF00u : 0x404044u;
        uint32_t color_s = (i == sat_field_idx) ? 0x4080FFu : 0x404044u;
        draw_label_bar(buf, x, bar_y_h, tick_w - 1, color_h);
        draw_label_bar(buf, x, bar_y_s, tick_w - 1, color_s);
    }

    // Print field names + seed to stdout — that's where the user reads details.
    fprintf(stderr, "\rseed=%-10u  H=%-22s  S=%-22s",
            ctx.map_seed,
            FIELDS[hue_field_idx].name,
            FIELDS[sat_field_idx].name);
    fflush(stderr);
}

static void render_all(void) {
    render_overview();
    render_inset();
    render_sidebar_text();
}

// ============================================================================
// Input handling
// ============================================================================
//
// fenster.keys is an array indexed by keycode. Codes per fenster's docs:
//   ASCII printable characters use their ASCII value
//   Special: 8=Backspace, 9=Tab, 10=Enter, 17=Ctrl, 16=Shift, 18=Alt, 27=Esc
//   Arrows: 17 (left? — fenster's mapping is OS-specific, we use printable keys)
//
// To stay portable, we use ASCII letter keys exclusively for control.

static int prev_keys[256];
static int prev_mouse_x = -1, prev_mouse_y = -1;
static int prev_mouse_btn = 0;

static int key_pressed(struct fenster *f, int code) {
    int now = f->keys[code];
    int was = prev_keys[code];
    return now && !was;
}

static void update_prev_keys(struct fenster *f) {
    memcpy(prev_keys, f->keys, sizeof(prev_keys));
}

static int handle_input(struct fenster *f) {
    // Returns 1 if a re-render is needed, 0 otherwise.
    int redraw = 0;

    if (f->keys[27]) return -1;   // ESC — signal quit

    // R: re-seed
    if (key_pressed(f, 'R') || key_pressed(f, 'r')) {
        ctx.map_seed = (uint32_t)rand() ^ ((uint32_t)rand() << 16);
        fprintf(stderr, "\n[reseed] %u\n", ctx.map_seed);
        redraw = 1;
    }

    // N / n: cycle hue field
    if (key_pressed(f, 'N') || key_pressed(f, 'n')) {
        // Shift+N cycles backward; we approximate with capital N.
        // fenster's shift-detection is OS-dependent, so we use 'n' forward,
        // 'b' backward as an alternative.
        hue_field_idx = (hue_field_idx + 1) % FIELDS_COUNT;
        redraw = 1;
    }
    if (key_pressed(f, 'B') || key_pressed(f, 'b')) {
        hue_field_idx = (hue_field_idx + FIELDS_COUNT - 1) % FIELDS_COUNT;
        redraw = 1;
    }

    // M / m: cycle saturation field forward; , (comma) cycles backward
    if (key_pressed(f, 'M') || key_pressed(f, 'm')) {
        sat_field_idx = (sat_field_idx + 1) % FIELDS_COUNT;
        redraw = 1;
    }
    if (key_pressed(f, ',')) {
        sat_field_idx = (sat_field_idx + FIELDS_COUNT - 1) % FIELDS_COUNT;
        redraw = 1;
    }

    // + / -: zoom inset
    if (key_pressed(f, '=') || key_pressed(f, '+')) {
        inset_half *= 0.5;
        if (inset_half < 100.0) inset_half = 100.0;
        redraw = 1;
    }
    if (key_pressed(f, '-') || key_pressed(f, '_')) {
        inset_half *= 2.0;
        if (inset_half > WORLD_HALF) inset_half = WORLD_HALF;
        redraw = 1;
    }

    // Mouse: clicking in the overview re-centers the inset there.
    if (f->mouse) {  // button down
        if (f->x < OVERVIEW_W && f->y < OVERVIEW_H && !prev_mouse_btn) {
            double pixel_size = 2.0 * WORLD_HALF / OVERVIEW_W;
            inset_cx = -WORLD_HALF + (f->x + 0.5) * pixel_size;
            inset_cy = -WORLD_HALF + (f->y + 0.5) * pixel_size;
            fprintf(stderr, "\n[inset] center=(%.0f, %.0f) half=%.0f\n",
                    inset_cx, inset_cy, inset_half);
            redraw = 1;
        }
    }
    prev_mouse_btn = f->mouse;
    prev_mouse_x = f->x;
    prev_mouse_y = f->y;

    update_prev_keys(f);
    return redraw;
}

// ============================================================================
// Main
// ============================================================================

int main(int argc, char **argv) {
    srand((unsigned)time(NULL));

    if (argc >= 2) {
        ctx.map_seed = (uint32_t)strtoul(argv[1], NULL, 10);
    } else {
        ctx.map_seed = (uint32_t)rand() ^ ((uint32_t)rand() << 16);
    }

    fprintf(stderr, "Geology prototype\n");
    fprintf(stderr, "  R           re-seed\n");
    fprintf(stderr, "  N / B       cycle hue field forward / backward\n");
    fprintf(stderr, "  M / ,       cycle saturation field forward / backward\n");
    fprintf(stderr, "  + / -       zoom inset in / out\n");
    fprintf(stderr, "  Click       re-center inset\n");
    fprintf(stderr, "  ESC         quit\n\n");
    fprintf(stderr, "Initial seed: %u\n", ctx.map_seed);

    struct fenster fen = {
        .title = "geo-proto",
        .width = WIN_W, .height = WIN_H,
        .buf = buf,
    };
    fenster_open(&fen);

    render_all();

    int64_t now = fenster_time();
    while (fenster_loop(&fen) == 0) {
        int r = handle_input(&fen);
        if (r < 0) break;
        if (r > 0) render_all();

        int64_t elapsed = fenster_time() - now;
        if (elapsed < 1000 / 60) fenster_sleep(1000 / 60 - elapsed);
        now = fenster_time();
    }

    fprintf(stderr, "\n");
    fenster_close(&fen);
    return 0;
}

