            redraw = 1;
        }
    }
    prev_mouse_btn = f->mouse;
    prev_mouse_x = f->x;
    prev_mouse_y = f->y;

    update_prev_keys(f);
    return redraw;
}

// ============================================================================
// Main
// ============================================================================

int main(int argc, char **argv) {
    srand((unsigned)time(NULL));

    if (argc >= 2) {
        ctx.map_seed = (uint32_t)strtoul(argv[1], NULL, 10);
    } else {
        ctx.map_seed = (uint32_t)rand() ^ ((uint32_t)rand() << 16);
    }

    fprintf(stderr, "Geology prototype\n");
    fprintf(stderr, "  R           re-seed\n");
    fprintf(stderr, "  N / B       cycle hue field forward / backward\n");
    fprintf(stderr, "  M / ,       cycle saturation field forward / backward\n");
    fprintf(stderr, "  + / -       zoom inset in / out\n");
    fprintf(stderr, "  Click       re-center inset\n");
    fprintf(stderr, "  ESC         quit\n\n");
    fprintf(stderr, "Initial seed: %u\n", ctx.map_seed);

    struct fenster fen = {
        .title = "geo-proto",
        .width = WIN_W, .height = WIN_H,
        .buf = buf,
    };
    fenster_open(&fen);

    render_all();

    int64_t now = fenster_time();
    while (fenster_loop(&fen) == 0) {
        int r = handle_input(&fen);
        if (r < 0) break;
        if (r > 0) render_all();

        int64_t elapsed = fenster_time() - now;
        if (elapsed < 1000 / 60) fenster_sleep(1000 / 60 - elapsed);
        now = fenster_time();
    }

    fprintf(stderr, "\n");
    fenster_close(&fen);
    return 0;
}

