// --- Layer 1: cratons ---
#define CRATON_GRID        3000
#define CRATON_JITTER      0.95
#define CONT_BIAS_SCALE    (1.0/30000.0)
#define CONT_BIAS_OUTPUT   0.4
#define CONT_THRESHOLD     0.45
// Radial centering: Pangaea is biased toward the origin so the player spawn
// is reliably continental. Falls off with distance from (0, 0) over RADIAL_FALLOFF
// tiles. Set RADIAL_STRENGTH to 0 to disable centering and let pure noise decide.
#define RADIAL_STRENGTH    0.35
#define RADIAL_FALLOFF     35000.0

// Continental bias is sampled at unwarped coordinates plus a radial term
// that biases the supercontinent to be centered near the origin.
double ux = f->wx - f->warp_coarse_x - f->warp_fine_x;
double uy = f->wy - f->warp_coarse_y - f->warp_fine_y;

double bias_noise = multioctave_noise(ux, uy, 0.5,
    ctx->map_seed, noise_layer_id("pangaea"), 2,
    CONT_BIAS_SCALE, CONT_BIAS_OUTPUT, 0, 0);

// Radial term: 1.0 at origin, falling smoothly to 0 at RADIAL_FALLOFF.
// Use a smoothstep-like falloff so the coastline isn't a hard circle.
double r = sqrt(ux * ux + uy * uy) / RADIAL_FALLOFF;
double radial = (r < 1.0) ? (1.0 - r * r) * (1.0 - r * r) : 0.0;

f->continental_bias = bias_noise + RADIAL_STRENGTH * radial;

