    int n_total = 0;
    int n_land = 0;
    int tect_count[7] = {0};
    int bnd_count[3] = {0};
    int n_endorheic = 0;
    double elev_min = 1e9, elev_max = -1e9, elev_sum = 0;
    double land_elev_min = 1e9, land_elev_max = -1e9, land_elev_sum = 0;

