    double half = 50000.0;
    for (int iy = 0; iy < N; ++iy) {
        for (int ix = 0; ix < N; ++ix) {
            double x = -half + (ix + 0.5) * (2*half/N);
            double y = -half + (iy + 0.5) * (2*half/N);
            geology_eval_all(x, y, &ctx, &f);
            n_total++;
            if (f.craton_continental > 0.5) {
                n_land++;
                if (f.elevation < land_elev_min) land_elev_min = f.elevation;
                if (f.elevation > land_elev_max) land_elev_max = f.elevation;
                land_elev_sum += f.elevation;
            }
            if (f.elevation < elev_min) elev_min = f.elevation;
            if (f.elevation > elev_max) elev_max = f.elevation;
            elev_sum += f.elevation;
            int t = (int)f.tectonic_setting;
            if (t >= 0 && t < 7) tect_count[t]++;
            int b = (int)f.boundary_type;
            if (b >= 0 && b < 3) bnd_count[b]++;
            if (f.endorheic_indicator > 0.5) n_endorheic++;
        }
    }

    printf("Sweep at 100x100 over [-50k, +50k]^2 with seed=%u:\n", ctx.map_seed);
    printf("  Land/total: %d / %d = %.1f%%\n", n_land, n_total, 100.0*n_land/n_total);
    printf("  Elevation range: [%+.3f, %+.3f] mean=%+.3f\n",
           elev_min, elev_max, elev_sum/n_total);
    if (n_land > 0) {
        printf("  Land elevation: [%+.3f, %+.3f] mean=%+.3f\n",
               land_elev_min, land_elev_max, land_elev_sum/n_land);
    }
    printf("  Endorheic basins: %d (%.1f%% of land)\n",
           n_endorheic, n_land > 0 ? 100.0*n_endorheic/n_land : 0);
    printf("  Tectonic settings:\n");
    const char *tect_names[] = {"ocean","passive","shield","platform","orogen","rift","basin"};
    for (int i = 0; i < 7; ++i) {
        printf("    %s: %d (%.1f%%)\n", tect_names[i], tect_count[i],
               100.0*tect_count[i]/n_total);
    }
    printf("  Boundary types:\n");
    const char *bnd_names[] = {"transform","divergent","convergent"};
    for (int i = 0; i < 3; ++i) {
        printf("    %s: %d (%.1f%%)\n", bnd_names[i], bnd_count[i],
               100.0*bnd_count[i]/n_total);
    }
    return 0;
}

