//! The [`Scalar`] trait: the storage-type abstraction for AD-ready code.
//!
//! Constitutive functions are written generically over a `V: Scalar` storage
//! type, so the same function body can be evaluated with `V = f64` (for plain
//! evaluation) or `V = Dual<f64>` (for forward-mode AD).
//!
//! The bounds collected in `Scalar` are exactly the operations our
//! constitutive functions need:
//!
//! - basic field arithmetic (`+ - * /`),
//! - elementary functions (`exp`, `ln`, `powi`, `powf`, `sqrt`),
//! - comparison and `min`/`max` for the rheology min-cap,
//! - conversion from `f64` for embedding constants.
//!
//! The trait is deliberately slim. We do **not** include things like `sin` /
//! `cos` / `atan2`: mantle constitutive laws don't use them, and pruning the
//! trait keeps trait-bound errors readable. Add operations as we need them,
//! never speculatively.
//!
//! `num_traits::Float` is a tempting shortcut here but it pulls in a lot we
//! don't need (NaN handling APIs, classification predicates) and a couple
//! things we don't want a generic constitutive function to call (`is_nan`
//! et al.). We keep our own trait and impl it for the storage types we use.

use core::ops::{Add, Sub, Mul, Div, Neg};

/// Storage type for dimensional quantities in AD-ready code.
///
/// Implementors: `f64`, and (future) `Dual<f64>` for forward-mode AD.
pub trait Scalar:
    Copy
    + Send
    + Sync
    + 'static
    + PartialOrd
    + From<f64>
    + Add<Output = Self>
    + Sub<Output = Self>
    + Mul<Output = Self>
    + Div<Output = Self>
    + Neg<Output = Self>
{
    /// The constant zero in this scalar type.
    fn zero() -> Self;
    /// The constant one in this scalar type.
    fn one() -> Self;

    /// e raised to self.
    fn exp(self) -> Self;
    /// Natural logarithm.
    fn ln(self) -> Self;
    /// Square root.
    fn sqrt(self) -> Self;
    /// Self raised to an integer power.
    fn powi(self, n: i32) -> Self;
    /// Self raised to a real power. The exponent is *another* `Scalar` value
    /// because in some viscosity formulae the exponent itself depends on
    /// position-dependent parameters; keeping it `Self`-typed lets AD flow
    /// through the exponent if it ever becomes a differentiable input.
    fn powf(self, exp: Self) -> Self;

    /// Pointwise minimum. Used in viscosity min-capping.
    ///
