//! Generic-tier dimensional aliases, parameterised by storage type `V`.
//!
//! These aliases expose `V` as a free parameter so that constitutive code can
//! be written once and evaluated with both `V = f64` and `V = Dual<f64>`.
//! Framework code that does not need AD-genericity should prefer the
//! [`super::scalar`] tier for ergonomics.
//!
//! All quantities here are SI-base-unit quantities from `uom::si`. The
//! mapping from project-local names to SI quantity names is the only
//! customisation done in this tier.

use uom::si;

// ---------------------------------------------------------------------------
// Configuration / mechanical inputs.
// ---------------------------------------------------------------------------

/// Length, m. Used for position components, depth, grain size.
pub type Length<V> = si::Length<si::SI<V>, V>;

/// Time, s.
pub type Time<V> = si::Time<si::SI<V>, V>;

/// Velocity, m/s.
pub type Velocity<V> = si::Velocity<si::SI<V>, V>;

/// Acceleration, m/s². Used for gravity.
pub type Acceleration<V> = si::Acceleration<si::SI<V>, V>;

/// Strain rate, 1/s. Dimensionally identical to frequency, but semantically
/// distinct: this is the magnitude of a deformation-rate tensor's invariant.
/// We re-use `uom::si::Frequency` for the dimensions; the semantic meaning
/// is conveyed by the name.
pub type StrainRate<V> = si::Frequency<si::SI<V>, V>;

// ---------------------------------------------------------------------------
// Thermodynamic state.
// ---------------------------------------------------------------------------

/// Pressure, Pa.
pub type Pressure<V> = si::Pressure<si::SI<V>, V>;

/// Temperature, K. Project name; SI calls this `ThermodynamicTemperature`.
pub type Temperature<V> = si::ThermodynamicTemperature<si::SI<V>, V>;

// ---------------------------------------------------------------------------
// EOS outputs.
// ---------------------------------------------------------------------------

/// Mass density, kg/m³.
pub type Density<V> = si::MassDensity<si::SI<V>, V>;

/// Thermal expansivity, 1/K.
/// SI quantity name is `TemperatureCoefficient`; project name is the one
/// the geophysics literature uses.
pub type ThermalExpansivity<V> = si::TemperatureCoefficient<si::SI<V>, V>;

/// Isothermal compressibility, 1/Pa.
/// Not a stock SI quantity name; declared in
/// [`super::project_quantities`] and re-exported here for uniform access.
pub type Compressibility<V> = super::project_quantities::Compressibility<V>;

/// Specific heat capacity, J/(kg·K).
pub type SpecificHeat<V> = si::SpecificHeatCapacity<si::SI<V>, V>;

// ---------------------------------------------------------------------------
// Transport outputs.
// ---------------------------------------------------------------------------

/// Dynamic viscosity, Pa·s.
pub type Viscosity<V> = si::DynamicViscosity<si::SI<V>, V>;

/// Thermal conductivity, W/(m·K).
pub type ThermalConductivity<V> = si::ThermalConductivity<si::SI<V>, V>;

// ---------------------------------------------------------------------------
// Energy / source quantities.
// ---------------------------------------------------------------------------

/// Energy, J. Used for thermodynamic potentials when expressed per particle.
pub type Energy<V> = si::Energy<si::SI<V>, V>;

/// Volumetric heat source rate, W/m³. Right-hand side of the energy equation.
/// Not a stock SI quantity; declared in [`super::project_quantities`].
pub type VolumetricHeatRate<V> = super::project_quantities::VolumetricHeatRate<V>;

// ---------------------------------------------------------------------------
// Per-mole quantities (for flow-law activation parameters and molar
// thermodynamic potentials).
// ---------------------------------------------------------------------------

/// Energy per mole, J/mol. Activation energy in flow laws; molar Gibbs energy.
pub type EnergyPerMole<V> = super::project_quantities::EnergyPerMole<V>;

/// Volume per mole, m³/mol. Activation volume in flow laws; molar volume.
pub type VolumePerMole<V> = super::project_quantities::VolumePerMole<V>;

// ---------------------------------------------------------------------------
// Dimensionless.
// ---------------------------------------------------------------------------

/// A pure ratio. Composition fractions, exponents, etc.
pub type Ratio<V> = si::Ratio<si::SI<V>, V>;

