//! Project-specific dimensional quantities not present in stock SI.
//!
//! When the geophysics literature uses a quantity that `uom::si` doesn't
//! pre-define (or pre-defines under a name with non-mantle conventions), we
//! declare it here. Each declaration is a thin alias built from the SI base
//! dimensions; the actual `uom::si::Quantity` type does the work.
//!
//! Add quantities here as new flow laws or constitutive forms surface a need.
//! Resist the temptation to pre-declare everything plausible — unused
//! quantities become deadweight in error messages and documentation.

use uom::si;
use uom::si::{ISQ, SI};
use uom::typenum::{N1, N3, P2, P3, Z0};

// ---------------------------------------------------------------------------
// Compressibility, 1/Pa.
//
// Dimensions: M^{-1} L T². (Inverse of pressure: Pa = M L^{-1} T^{-2}.)
// SI ships an `Inverse` quantity adapter, but for clarity and to give it a
// project-meaningful name we declare it via `ISQ`.
// ---------------------------------------------------------------------------

pub type Compressibility<V> = si::Quantity<
    ISQ<
        N1, // M (mass)  -1
        si::P1,                 // L (length) +1   -- wait: 1/Pa = m·s²/kg.
        P2, // T (time)  +2
        Z0, // I (current)
        Z0, // Θ (temperature)
        Z0, // N (amount)
        Z0, // J (luminous intensity)
    >,
    SI<V>,
    V,
>;

// ---------------------------------------------------------------------------
// Volumetric heat source rate, W/m³ = kg / (m · s³).
//
// Dimensions: M L^{-1} T^{-3}.
// ---------------------------------------------------------------------------

pub type VolumetricHeatRate<V> = si::Quantity<
    ISQ<
        si::P1,                 // M
        N1, // L
        N3, // T
        Z0, Z0, Z0, Z0,
    >,
    SI<V>,
    V,
>;

// ---------------------------------------------------------------------------
// Energy per mole, J/mol = kg · m² / (s² · mol).
//
// Dimensions: M L² T^{-2} N^{-1}.
// ---------------------------------------------------------------------------

pub type EnergyPerMole<V> = si::Quantity<
    ISQ<
        si::P1,                 // M
        P2, // L
        si::N2,                 // T
        Z0,
        Z0,
        N1, // N (amount)
        Z0,
    >,
    SI<V>,
    V,
>;

// ---------------------------------------------------------------------------
// Volume per mole, m³/mol.
//
// Dimensions: L³ N^{-1}.
// ---------------------------------------------------------------------------

pub type VolumePerMole<V> = si::Quantity<
    ISQ<
        Z0,
        P3, // L
        Z0,
        Z0,
        Z0,
        N1, // N
        Z0,
    >,
    SI<V>,
    V,
>;

